<?php
ob_start();session_id('nstBankReport'.bin2hex(random_bytes(8)));session_start();$_SESSION['user']='superadmin';$cookie='PHPSESSID='.session_id();session_write_close();
try{foreach(['bancos/reporte?desde=2026-10-01&hasta=2026-10-31','bancos/reporte/pdf?desde=2026-10-01&hasta=2026-10-31'] as $route){$c=curl_init('http://localhost/api/index.php/'.$route);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIE=>$cookie,CURLOPT_TIMEOUT=>30]);$body=curl_exec($c);$code=curl_getinfo($c,CURLINFO_HTTP_CODE);curl_close($c);if($code!==200)throw new Exception('HTTP '.$code.' '.substr($body,0,150));if(strpos($route,'/pdf')!==false){if(substr($body,0,5)!=='%PDF-')throw new Exception('Invalid PDF');file_put_contents(__DIR__.'/../output/pdf/Reporte_Bancos_2026-10.pdf',$body);}else{$d=json_decode($body,true);if(count($d['Cuentas'])!==2)throw new Exception('Wrong accounts');}echo $route.' HTTP 200 verified'.PHP_EOL;}}
finally{session_start();$_SESSION=[];session_destroy();ob_end_flush();}
